  const colorRaw = String(source.color || '').trim();
  const colorDup = colorRaw && name.replace(/\s+/g, '').includes(colorRaw.replace(/\s+/g, ''));
  const option = [colorDup ? '' : colorRaw, sanitizeScanSize(source.size || '')].filter(Boolean).join(' / ').replace(/[_＿]+/g, ' ').replace(/\s+/g, ' ').trim();
  const unitPrice = metrics.quantity ? Math.floor(metrics.saleTotal / metrics.quantity) : metrics.saleTotal;
